/* ===== LESSON CONTENT (20 core lessons) ===== */
var REF_VERIFIED = '26/11/2026';
var SEL = 'https://www.selenium.dev/documentation/webdriver/';
var SELAPI = 'https://www.selenium.dev/selenium/docs/api/java/org/openqa/selenium/';
var LESSONS = [
{ id: 1, day: 1, title: 'Selenium & kiến trúc WebDriver', sub: 'Selenium điều khiển trình duyệt như thế nào?',
  obj: ['Phân biệt Selenium, WebDriver, trình duyệt và driver.', 'Mô tả đường đi của một lệnh từ Java tới trình duyệt và ngược lại.', 'Biết vì sao Selenium không phải là công cụ đọc màn hình.'],
  theory: { what: 'Selenium là bộ công cụ mã nguồn mở để tự động hóa trình duyệt. WebDriver là API (bộ lệnh) để test code gửi lệnh tới trình duyệt. Trình duyệt được điều khiển thông qua một driver riêng (ví dụ ChromeDriver).', why: 'Kiểm thử giao diện web lặp đi lặp lại (regression) rất tốn công nếu làm tay. Selenium giúp chạy lại tự động cùng một kịch bản trên nhiều lần build.', when: 'Dùng để kiểm thử chức năng giao diện web, hồi quy (regression), kiểm thử trên nhiều trình duyệt.', how: 'Test script (Java) → WebDriver API → driver của trình duyệt (chuẩn W3C WebDriver) → trình duyệt. Trình duyệt trả kết quả về theo chiều ngược lại.', whenNot: 'Không dùng để kiểm thử API thuần, kiểm tra hiệu năng tải trang, hay thay thế kiểm thử thủ công cho UX/cảm nhận người dùng.' },
  beginner: { analogy: 'Giống một người điều khiển từ xa (test script) bấm nút trên remote (WebDriver), tín hiệu đi qua bộ thu hồng ngoại (driver) tới chiếc TV (trình duyệt). TV làm việc rồi gửi trạng thái về để bạn biết.', text: 'Mỗi lệnh bạn viết (ví dụ mở trang, bấm nút) không tự làm gì trên màn hình. Lệnh được gửi đi, trình duyệt thực hiện, rồi trả về kết quả hoặc lỗi. Nếu bạn hiểu điều này, bạn sẽ hiểu được nhiều lỗi sau này.', terms: [['Test script', 'Đoạn code Java bạn viết để kiểm thử.'], ['WebDriver', 'Bộ API Java để gửi lệnh tới trình duyệt.'], ['Driver (ChromeDriver...)', 'Chương trình trung gian biết cách nói chuyện với một trình duyệt cụ thể.'], ['API', 'Bộ lệnh có tên và tham số để chương trình khác gọi.']] },
  code: ['import org.openqa.selenium.WebDriver;', 'import org.openqa.selenium.chrome.ChromeDriver;', '', 'public class FirstVisit {', '    public static void main(String[] args) {', '        WebDriver driver = new ChromeDriver();', '        driver.get("https://example.com");', '        System.out.println(driver.getTitle());', '        driver.quit();', '    }', '}'],
  codeExplain: [['import org.openqa.selenium.WebDriver;', 'Nhập interface WebDriver — "bộ điều khiển" chung cho mọi trình duyệt.'], ['new ChromeDriver()', 'Khởi tạo một phiên (session) với Chrome. Từ Selenium 4.6, Selenium Manager tự tải đúng driver nếu cần.'], ['driver.get("...")', 'Yêu cầu trình duyệt mở URL và chờ trang tải theo pageLoadStrategy.'], ['driver.getTitle()', 'Lấy tiêu đề trang (thẻ <title>) để kiểm tra.'], ['driver.quit()', 'Đóng mọi cửa sổ và kết thúc phiên. Luôn gọi để không để lại tiến trình trình duyệt treo.']],
  mistakes: [['Nghĩ Selenium là một trình duyệt.', 'Selenium là thư viện/bộ công cụ; trình duyệt là phần mềm khác, cần driver tương ứng.'], ['Quên gọi driver.quit().', 'Dùng try/finally hoặc @AfterMethod để luôn đóng phiên.'], ['Nghĩ lệnh thành công nghĩa là giao diện đã đúng.', 'Luôn kiểm tra kết quả bằng assertion, không chỉ dựa vào việc lệnh không ném exception.']],
  refs: [['WebDriver — Drivers', 'Trang giải thích driver của từng trình duyệt', SEL + 'drivers/'], ['WebDriver (Javadoc)', 'Interface WebDriver — quit(), get(), getTitle()', SELAPI + 'WebDriver.html'], ['W3C WebDriver Specification', 'Đặc tả chuẩn của giao thức WebDriver', 'https://www.w3.org/TR/webdriver/']] },

{ id: 2, day: 1, title: 'Điều hướng trình duyệt (Navigation)', sub: 'get, navigate, back, forward, close và quit', obj: ['Mở URL bằng get() và navigate().to().', 'Dùng back(), forward(), refresh().', 'Phân biệt close() và quit().'],
  theory: { what: 'Các lệnh điều hướng cho phép test mở trang, quay lại trang trước, tải lại và đóng cửa sổ/phiên.', why: 'Nhiều kịch bản cần di chuyển trong lịch sử trình duyệt, ví dụ kiểm tra nút Back của ứng dụng.', when: 'Khi cần mở URL, đi qua lại giữa các trang, hoặc kết thúc test.', how: 'driver.get(url) hoặc driver.navigate().to(url) gửi lệnh tải trang. navigate() còn có back(), forward(), refresh(). close() đóng cửa sổ hiện tại; quit() đóng mọi cửa sổ và kết thúc session.', whenNot: 'Không dùng driver.navigate().back() để "chờ" trang; hãy dùng wait có điều kiện.'},
  beginner: { analogy: 'Trình duyệt giống quyển sổ lịch sử. get() là viết địa chỉ mới rồi mở; back() là lật trang về trang trước. close() là đóng một tab; quit() là đóng cả quyển sổ và cất đi.', text: 'Sự khác biệt quan trọng nhất: close() chỉ đóng cửa sổ hiện tại, quit() đóng tất cả cửa sổ và kết thúc phiên WebDriver.', terms: [['URL', 'Địa chỉ của một trang web, ví dụ https://example.com.'], ['Session', 'Một phiên làm việc giữa test và trình duyệt.'], ['Window handle', 'Mã định danh của một cửa sổ/tab.']] },
  code: ['WebDriver driver = new ChromeDriver();', 'driver.get("https://shop.example.com");', 'driver.navigate().to("https://shop.example.com/cart");', 'driver.navigate().back();', 'driver.navigate().forward();', 'driver.navigate().refresh();', 'driver.close();   // đóng tab hiện tại', 'driver.quit();    // đóng tất cả và kết thúc session'],
  codeExplain: [['driver.get(url)', 'Mở URL và chờ trang tải theo pageLoadStrategy.'], ['driver.navigate().to(url)', 'Cũng mở URL, thuộc nhóm lệnh Navigation (Javadoc WebDriver.Navigation).'], ['navigate().back() / forward()', 'Đi lùi/tiến trong lịch sử trình duyệt.'], ['close()', 'Đóng cửa sổ hiện tại. Nếu còn cửa sổ khác, session vẫn chạy.'], ['quit()', 'Đóng mọi cửa sổ và kết thúc session. Sau đó driver không dùng được nữa.']],
  mistakes: [['Dùng close() ở cuối test rồi nghĩ trình duyệt đã tắt hẳn.', 'Dùng quit() để kết thúc toàn bộ session.'], ['Dùng Thread.sleep sau back().', 'Chờ điều kiện cụ thể bằng WebDriverWait.'], ['Gọi lệnh sau quit().', 'Tạo driver mới hoặc đặt quit() ở cuối vòng đời test.']],
  refs: [['Browser manipulation', 'Trang hướng dẫn điều khiển trình duyệt (get, navigate, window)', SEL + 'browser_manipulation/'], ['WebDriver.Navigation (Javadoc)', 'back(), forward(), refresh(), to(String)', SELAPI + 'WebDriver.Navigation.html'], ['WebDriver (Javadoc)', 'close() và quit()', SELAPI + 'WebDriver.html']] },

{ id: 3, day: 1, title: 'HTML, DOM và Locators', sub: 'Tìm phần tử bằng id, name, class, tag, link text', obj: ['Hiểu HTML là cấu trúc và DOM là cây đang chạy trong trình duyệt.', 'Chọn locator ổn định nhất.', 'Dùng By.id, By.name, By.className, By.tagName, By.linkText.'], theory: { what: 'Locator là cách mô tả để Selenium tìm đúng phần tử trên trang. DOM (Document Object Model) là cây đối tượng do trình duyệt dựng từ HTML.', why: 'Mọi thao tác (click, nhập chữ) đều cần tìm đúng phần tử trước.', when: 'Dùng id/name khi có; dùng CSS/XPath khi không có thuộc tính đơn giản.', how: 'Selenium gửi locator (By) tới trình duyệt, trình duyệt tìm trên DOM và trả về WebElement (tham chiếu tới phần tử).', whenNot: 'Không dùng locator dựa trên vị trí hay chỉ số (ví dụ "phần tử thứ 3") khi có thể dùng thuộc tính rõ nghĩa.' }, beginner: { analogy: 'Trang web giống một tòa nhà. HTML là bản thiết kế; DOM là tòa nhà thực tế với các phòng. Locator giống địa chỉ "phòng có số 12 ở tầng 3" — số phòng (id) thì tốt nhất vì ít đổi.', text: 'id phải là duy nhất trên một trang. class có thể dùng cho nhiều phần tử, nên thường không đủ để xác định một phần tử.', terms: [['HTML', 'Ngôn ngữ đánh dấu mô tả cấu trúc trang.'], ['DOM', 'Cây đối tượng của trang đang chạy trong trình duyệt.'], ['Attribute', 'Thuộc tính của thẻ, ví dụ id="username".'], ['Locator (By)', 'Cách mô tả phần tử để tìm.']] }, code: ['// <input id="username" name="user" class="form-input">', 'WebElement user = driver.findElement(By.id("username"));', 'WebElement byName = driver.findElement(By.name("user"));', 'WebElement byClass = driver.findElement(By.className("form-input"));', 'WebElement link = driver.findElement(By.linkText("Đăng ký"));'], codeExplain: [['By.id("username")', 'Tìm theo thuộc tính id; nhanh và ổn định nếu id không đổi.'], ['By.name("user")', 'Tìm theo thuộc tính name, thường dùng với form cũ.'], ['By.className("form-input")', 'Tìm theo class. Nếu nhiều phần tử có cùng class, findElement lấy phần tử đầu tiên — dễ gây sai.'], ['By.linkText("Đăng ký")', 'Tìm thẻ <a> có text khớp chính xác.']], mistakes: [['Dùng id động như "input_8fd2a".', 'Chọn thuộc tính ổn định khác hoặc quan hệ với phần tử gần đó.'], ['Dùng class khi trang có nhiều phần tử cùng class.', 'Kết hợp tag/thuộc tính, hoặc dùng XPath/CSS cụ thể hơn.'], ['Dùng locator dựa trên vị trí (nth-child).', 'Ưu tiên thuộc tính có nghĩa như data-testid nếu có.']], refs: [['Locating elements', 'Hướng dẫn các locator (By.id, By.name, ...)', SEL + 'elements/locators/'], ['DOM Introduction (MDN)', 'Giới thiệu DOM', 'https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model/Introduction'], ['By (Javadoc)', 'Các factory method của By', SELAPI + 'By.html']] },

{ id: 4, day: 1, title: 'XPath', sub: 'Ngôn ngữ truy vấn cây DOM', obj: ['Viết XPath theo text, thuộc tính, quan hệ cha-con, anh-em.', 'Phân biệt absolute và relative XPath.'], theory: { what: 'XPath là ngôn ngữ mô tả đường đi trong cây XML/HTML. Selenium dùng XPath để tìm phần tử theo cấu trúc hoặc nội dung.', why: 'Khi phần tử không có id/name, XPath cho phép mô tả quan hệ như "nút nằm trong form có tiêu đề Login".', when: 'Khi cần tìm theo text, theo quan hệ cha/con/anh em, hoặc theo nhiều điều kiện.', how: '//tag[@attr="giá trị"] tìm phần tử ở bất kỳ đâu; /html/body/... là đường dẫn tuyệt đối từ gốc; các trục như parent::, following-sibling:: đi theo quan hệ.', whenNot: 'Không dùng absolute XPath (đường đi từ /html) vì chỉ cần một thẻ thêm vào là vỡ.' }, beginner: { analogy: 'XPath giống chỉ đường: "đi từ trường, rẽ vào lớp 5A, người ngồi thứ hai sau bạn Lan". Đường tuyệt đối là "từ cổng số 1, đi 40 bước" — chỉ cần công trường thay đổi là lạc.', text: 'Quan hệ thường dùng: cha (parent), con (child), tổ tiên (ancestor), hậu duệ (descendant), anh em kế tiếp (following-sibling).', terms: [['Node', 'Một mắt xích trong cây DOM (thẻ, text...).'], ['Axis', 'Hướng đi trên cây, ví dụ parent, child, following-sibling.'], ['Predicate', 'Điều kiện trong ngoặc vuông, ví dụ [@id="x"].']] }, code: ['// Tìm theo text', 'driver.findElement(By.xpath("//button[normalize-space()=\'Đăng nhập\']"));', '// Tìm theo thuộc tính', 'driver.findElement(By.xpath("//input[@type=\'email\']"));', '// Quan hệ cha → con', 'driver.findElement(By.xpath("//div[@id=\'form\']/input[@name=\'user\']"));', '// Anh em kế tiếp', 'driver.findElement(By.xpath("//label[text()=\'Mật khẩu\']/following-sibling::input"));', '// Absolute (KHÔNG khuyến nghị)', 'driver.findElement(By.xpath("/html/body/div[2]/form/input[1]"));'], codeExplain: [['//button[normalize-space()=...]', 'Tìm nút có text (đã bỏ khoảng trắng thừa) khớp. Dấu // = bất kỳ vị trí nào trong cây.'], ['[@type=\'email\']', 'Điều kiện theo thuộc tính.'], ['/input[@name=...]', 'Dấu / = con trực tiếp.'], ['following-sibling::input', 'Lấy ô nhập nằm sau nhãn "Mật khẩu" cùng cấp.'], ['/html/body/div[2]/...', 'Đường tuyệt đối: dễ vỡ khi cấu trúc thay đổi.']], mistakes: [['Dùng absolute XPath.', 'Dùng relative //tag[@attr] có điều kiện rõ ràng.'], ['Dùng text() khi text có khoảng trắng.', 'Dùng normalize-space().'], ['Nghĩ XPath luôn chậm hơn CSS.', 'Hiệu năng khác nhau tùy trường hợp; tính đúng và ổn định quan trọng hơn.']], refs: [['Locating elements (XPath)', 'Phần XPath trong trang locator', SEL + 'elements/locators/'], ['XPath (MDN)', 'Tổng quan XPath trên web', 'https://developer.mozilla.org/en-US/docs/Web/XPath'], ['By.xpath (Javadoc)', 'Factory method By.xpath', SELAPI + 'By.html']] },

{ id: 5, day: 1, title: 'CSS Selector', sub: 'Chọn phần tử theo cú pháp CSS', obj: ['Viết selector theo #id, .class, [attribute], tag và kết hợp.', 'So sánh CSS với XPath.'], theory: { what: 'CSS selector là cú pháp dùng để chọn phần tử trong CSS. Selenium dùng By.cssSelector để tìm phần tử bằng cú pháp này.', why: 'Ngắn gọn, nhanh, dễ đọc hơn nhiều XPath.', when: 'Dùng cho hầu hết locator: id, class, thuộc tính, tổ hợp tag.', how: 'Trình duyệt áp selector lên DOM và trả về các phần tử khớp. Với findElement, lấy phần tử đầu tiên.', whenNot: 'CSS không đi ngược lên cha (không có parent trực tiếp) và không tìm theo text như XPath.'}, beginner: { analogy: 'CSS selector giống cách gọi món theo nhãn: "#main-form" là món có tên duy nhất; ".btn" là mọi món thuộc nhóm nút; "[type=email]" là món có ghi chú loại email.', text: 'Cú pháp CSS ngắn: #id, .class, tag, [attr="value"], và có thể ghép: button.btn[type="submit"].', terms: [['Selector', 'Biểu thức chọn phần tử.'], ['Class', 'Nhãn nhóm, có thể nhiều phần tử cùng class.'], ['Attribute', 'Thuộc tính như type, name, data-testid.']] }, code: ['driver.findElement(By.cssSelector("#login-btn"));', 'driver.findElement(By.cssSelector(".alert.alert-danger"));', 'driver.findElement(By.cssSelector("input[name=\'email\']"));', 'driver.findElement(By.cssSelector("button.btn[type=\'submit\']"));', 'driver.findElement(By.cssSelector("form#login input[type=\'password\']"));'], codeExplain: [['#login-btn', 'Chọn theo id.'], ['.alert.alert-danger', 'Phần tử có cả hai class.'], ['input[name=\'email\']', 'Chọn input có thuộc tính name là email.'], ['button.btn[type=\'submit\']', 'Kết hợp tag, class và attribute.'], ['form#login input[...]', 'Input là hậu duệ của form có id login.']], mistakes: [['Viết selector quá dài theo cấu trúc.', 'Chọn thuộc tính ngắn, ổn định.'], ['Nhầm #id và .class.', '# là id (duy nhất), . là class (có thể nhiều).'], ['Dùng selector có text tiếng Việt không khớp dấu.', 'Kiểm tra text chính xác hoặc dùng attribute khác.']], refs: [['Locating elements (CSS)', 'Phần CSS selector', SEL + 'elements/locators/'], ['Attribute selectors (MDN)', 'Cú pháp [attr] và [attr=value]', 'https://developer.mozilla.org/en-US/docs/Web/CSS/Attribute_selectors'], ['Element.querySelector (MDN)', 'Cách trình duyệt áp CSS selector', 'https://developer.mozilla.org/en-US/docs/Web/API/Element/querySelector']] },

{ id: 6, day: 1, title: 'findElement() và findElements()', sub: 'Một phần tử hay danh sách?', obj: ['Phân biệt findElement và findElements.', 'Biết khi nào gặp NoSuchElementException và khi nào nhận list rỗng.'], theory: { what: 'findElement trả về một WebElement (phần tử đầu tiên khớp). findElements trả về List<WebElement>.', why: 'Cần đúng số lượng: một nút, hay đếm sản phẩm.', when: 'findElement khi chắc chỉ có một phần tử; findElements khi cần đếm hoặc duyệt danh sách.', how: 'findElement không tìm thấy thì ném NoSuchElementException (sau khi áp dụng implicit wait nếu có). findElements không tìm thấy trả về danh sách rỗng.', whenNot: 'Không dùng findElement để kiểm tra "có tồn tại không" khi phần tử có thể không xuất hiện — dùng findElements().isEmpty() hoặc wait.' }, beginner: { analogy: 'findElement là "tìm người đầu tiên mặc áo đỏ"; findElements là "gọi tên tất cả người mặc áo đỏ và đếm". Nếu không ai mặc áo đỏ, findElement báo lỗi, còn findElements chỉ trả về danh sách trống.', text: 'List rỗng không phải là lỗi, đó là kết quả hợp lệ.', terms: [['List', 'Danh sách có thứ tự, có thể rỗng.'], ['Exception', 'Lỗi được ném ra khi chương trình gặp tình huống bất thường.']] }, code: ['WebElement btn = driver.findElement(By.id("submit"));', 'List<WebElement> products = driver.findElements(By.cssSelector(".product-card"));', 'System.out.println("Số sản phẩm: " + products.size());', 'boolean hasBanner = driver.findElements(By.id("promo")).size() > 0;'], codeExplain: [['findElement(By.id("submit"))', 'Lấy một phần tử; lỗi nếu không có.'], ['findElements(...)', 'Lấy tất cả phần tử khớp; có thể rỗng.'], ['products.size()', 'Đếm số phần tử.'], ['findElements(...).size() > 0', 'Cách kiểm tra tồn tại không ném lỗi.']], mistakes: [['Nghĩ findElements ném lỗi khi không có kết quả.', 'Nó trả về danh sách rỗng.'], ['Bắt NoSuchElementException để kiểm tra hiển thị.', 'Dùng isDisplayed hoặc wait theo điều kiện.'], ['Dùng findElement cho danh sách sản phẩm.', 'Dùng findElements và duyệt.']], refs: [['Finding elements', 'findElement và findElements trong Selenium', SEL + 'elements/finders/'], ['WebDriver (Javadoc)', 'Các phương thức findElement/findElements', SELAPI + 'WebDriver.html'], ['NoSuchElementException (Javadoc)', 'Ngoại lệ khi không tìm thấy phần tử', SELAPI + 'NoSuchElementException.html']] },

{ id: 7, day: 1, title: 'WebElement — click, sendKeys và thuộc tính', sub: 'Thao tác với phần tử và đọc trạng thái', obj: ['Dùng click, sendKeys, clear, getText.', 'Phân biệt getText, getAttribute, getDomAttribute.', 'Phân biệt isDisplayed, isEnabled, isSelected.'], theory: { what: 'WebElement là tham chiếu tới một phần tử trên trang. Có thể thao tác (click, sendKeys) và đọc thông tin (text, attribute, trạng thái).', why: 'Đây là các hành động người dùng thật làm: bấm, gõ, đọc chữ trên màn hình.', when: 'Sau khi tìm được phần tử. Đọc trạng thái khi cần khẳng định kết quả.', how: 'click() gửi lệnh bấm; sendKeys() gửi phím; getText() lấy chữ hiển thị; getAttribute(name) trả về giá trị property nếu có, nếu không thì attribute; getDomAttribute(name) đọc attribute trong DOM.', whenNot: 'Không dùng JavaScript click để thay thế click thật trong test hành vi người dùng; xem bài 16.'}, beginner: { analogy: 'Phần tử là một ô trên bảng điều khiển: click là bấm nút, sendKeys là gõ chữ, getText là đọc dòng chữ trên màn hình, còn attribute là ghi chú ẩn phía sau.', text: 'Hai câu hỏi hay gặp: "Phần tử đang hiển thị không?" (isDisplayed) và "Phần tử có bấm được không?" (isEnabled). Đừng nhầm hai câu này.', terms: [['getText', 'Chữ hiển thị cho người dùng.'], ['Attribute', 'Thông tin trong thẻ, ví dụ href, value.'], ['Property', 'Giá trị hiện tại trong đối tượng DOM, ví dụ value của ô nhập.']] }, code: ['WebElement email = driver.findElement(By.id("email"));', 'email.clear();', 'email.sendKeys("qa@example.com");', 'WebElement submit = driver.findElement(By.id("submit"));', 'submit.click();', 'String msg = driver.findElement(By.id("msg")).getText();', 'String type = email.getDomAttribute("type");', 'boolean shown = submit.isDisplayed();'], codeExplain: [['clear()', 'Xóa nội dung ô nhập trước khi gõ.'], ['sendKeys("...")', 'Gõ chuỗi vào phần tử (cần phần tử nhận focus được).'], ['click()', 'Bấm phần tử bằng cơ chế WebDriver.'], ['getText()', 'Lấy chữ hiển thị.'], ['getDomAttribute("type")', 'Đọc attribute trong DOM.'], ['isDisplayed()', 'Có đang hiển thị với người dùng không.']], mistakes: [['Dùng getText để đọc giá trị ô input.', 'Dùng getAttribute("value") hoặc getDomProperty("value").'], ['Nghĩ isDisplayed đồng nghĩa isEnabled.', 'Hiển thị và được phép thao tác là hai điều kiện khác nhau.'], ['Gõ vào ô chưa được focus hoặc đang disabled.', 'Chờ phần tử clickable/enabled trước.']], refs: [['Element interactions', 'click, sendKeys, clear', SEL + 'elements/interactions/'], ['Element information', 'isDisplayed, getText, attributes', SEL + 'elements/information/'], ['WebElement (Javadoc)', 'getAttribute, getDomAttribute, getDomProperty', SELAPI + 'WebElement.html']] },

{ id: 8, day: 2, title: 'Implicit Wait', sub: 'Chờ ngầm khi tìm phần tử', obj: ['Giải thích implicit wait áp dụng khi nào.', 'Biết vì sao implicit wait không luôn chờ đủ timeout.', 'Hiểu rủi ro khi trộn implicit và explicit.'], theory: { what: 'Implicit wait là thời gian tối đa driver chờ khi tìm phần tử mà chưa thấy. Đặt một lần cho cả session.', why: 'Trang có phần tử xuất hiện chậm, việc chờ thủ công ở mỗi lệnh rất lặp lại.', when: 'Dùng ở mức đơn giản khi toàn bộ ứng dụng tải chậm đều đặn. Thường chỉ đặt một lần ở setup.', how: 'Khi findElement không thấy ngay, driver thử lại liên tục đến khi tìm thấy hoặc hết thời gian. Nếu tìm thấy sớm thì trả về ngay.', whenNot: 'Không dùng để chờ điều kiện cụ thể (đã hiển thị, đã bấm được); không trộn với explicit wait.'}, beginner: { analogy: 'Implicit wait giống việc bạn đặt chung một quy tắc cho cả nhà: "Khi tìm ai đó, đợi tối đa 10 giây trước khi bỏ cuộc". Nếu người đó đến sau 2 giây thì bạn đi tiếp luôn, không đợi thêm.', text: 'Nó chỉ áp dụng khi tìm phần tử, không áp dụng cho mọi lệnh như click hay get.', terms: [['Timeout', 'Thời gian tối đa được phép chờ.'], ['Session', 'Phiên làm việc với trình duyệt.']] }, code: ['WebDriver driver = new ChromeDriver();', 'driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(10));', 'driver.get("https://example.com/slow");', 'WebElement report = driver.findElement(By.id("report"));  // chờ tối đa 10s', 'System.out.println(report.getText());'], codeExplain: [['implicitlyWait(Duration.ofSeconds(10))', 'Đặt thời gian chờ ngầm tối đa 10 giây cho việc tìm phần tử.'], ['driver.get(...)', 'Lệnh này không dùng implicit wait để chờ như một tìm kiếm phần tử.'], ['findElement(By.id("report"))', 'Nếu có sau 3 giây, trả về ngay; nếu sau 10 giây vẫn chưa có, ném NoSuchElementException.']], mistakes: [['Nghĩ luôn chờ đủ 10 giây.', 'Nếu tìm thấy sớm, driver trả về ngay.'], ['Trộn implicit với WebDriverWait.', 'Kết quả chờ có thể khó đoán, Selenium cảnh báo không trộn.'], ['Đặt implicit wait rất lớn để "cho chắc".', 'Dùng explicit wait cụ thể cho từng điều kiện.']], refs: [['Waits — Implicit waits', 'Mục Implicit waits và cảnh báo không trộn implicit với explicit', SEL + 'waits/'], ['WebDriver.Timeouts (Javadoc)', 'implicitlyWait(Duration)', SELAPI + 'WebDriver.Timeouts.html']] },

{ id: 9, day: 2, title: 'Explicit Wait', sub: 'Chờ theo một điều kiện cụ thể', obj: ['Dùng WebDriverWait với ExpectedConditions.', 'Hiểu TimeoutException.', 'Chọn đúng điều kiện: presence, visibility, clickable.'], theory: { what: 'Explicit wait chờ cho đến khi một điều kiện cụ thể đúng, hoặc hết thời gian. WebDriverWait là cách làm phổ biến.', why: 'Mỗi phần tử có thể cần điều kiện khác nhau (có trong DOM, hiển thị, bấm được).', when: 'Khi trang có thao tác bất đồng bộ: nút bị disable, thông báo hiện sau AJAX.', how: 'wait.until(condition) gọi điều kiện theo chu kỳ polling. Nếu điều kiện trả về giá trị "có" (không null/false) thì dừng; hết timeout ném TimeoutException.', whenNot: 'Không dùng sleep cố định thay cho explicit wait.'}, beginner: { analogy: 'Giống chờ đồ ăn: bạn không chờ "10 phút cứ thế" mà chờ đúng điều kiện "món đã được mang ra bàn". Nếu quá 10 phút mà chưa có, bạn báo lỗi (TimeoutException).', text: 'Điều kiện phải được viết rõ: "phần tử đã có trong DOM", "phần tử đã hiển thị", "phần tử bấm được".', terms: [['Condition', 'Điều kiện được kiểm tra lặp lại.'], ['Polling', 'Kiểm tra điều kiện theo chu kỳ.'], ['TimeoutException', 'Lỗi hết thời gian chờ.']] }, code: ['WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(5));', 'WebElement loginBtn = wait.until(', '    ExpectedConditions.elementToBeClickable(By.id("login")));', 'loginBtn.click();', '', '// Chờ thông báo hiển thị', 'wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("toast")));'], codeExplain: [['new WebDriverWait(driver, Duration.ofSeconds(5))', 'Tạo bộ chờ tối đa 5 giây.'], ['elementToBeClickable(By.id("login"))', 'Chờ phần tử hiển thị, enabled và đủ điều kiện bấm; vẫn có thể bị phần tử khác che.'], ['visibilityOfElementLocated', 'Chờ phần tử có trong DOM và hiển thị.']], mistakes: [['Dùng Thread.sleep(5000).', 'Dùng explicit wait theo điều kiện.'], ['Nghĩ elementToBeClickable đảm bảo không có gì che phần tử.', 'Điều kiện này không kiểm tra việc che chắn; click có thể bị ElementClickInterceptedException.'], ['Nhầm presence với visibility.', 'Presence là có trong DOM; visibility là hiển thị.']], refs: [['Waits — Explicit waits', 'WebDriverWait và điều kiện', SEL + 'waits/'], ['WebDriverWait (Javadoc)', 'Lớp WebDriverWait', SELAPI + 'support/ui/WebDriverWait.html'], ['ExpectedConditions (Javadoc)', 'Các điều kiện chờ dựng sẵn', SELAPI + 'support/ui/ExpectedConditions.html']] },

{ id: 10, day: 2, title: 'Fluent Wait', sub: 'Chờ có tùy chọn timeout, polling, bỏ qua exception', obj: ['Cấu hình timeout, polling interval và ignoring.', 'Hiểu WebDriverWait là lớp mở rộng của FluentWait.'], theory: { what: 'FluentWait cho phép cấu hình: tổng thời gian chờ (withTimeout), chu kỳ kiểm tra (pollingEvery), và các exception được bỏ qua trong lúc chờ (ignoring).', why: 'Trang có điều kiện kiểm tra tốn thời gian hoặc tạm thời ném lỗi trong lúc tải.', when: 'Khi cần kiểm soát chu kỳ polling hoặc bỏ qua một số exception tạm thời.', how: 'Bộ chờ gọi điều kiện theo pollingEvery; nếu gặp exception nằm trong ignoring thì coi như chưa đạt và thử tiếp.', whenNot: 'Với điều kiện đơn giản, WebDriverWait với ExpectedConditions là đủ.'}, beginner: { analogy: 'Giống thầy giáo gọi học sinh: "Cứ 2 giây hỏi một lần trong 30 giây; nếu học sinh đang ra ngoài (exception tạm thời) thì bỏ qua, hỏi lại".', text: 'Trong Selenium 4, WebDriverWait là lớp con của FluentWait, nên có các tùy chọn tương tự.', terms: [['Polling', 'Lặp lại kiểm tra theo chu kỳ.'], ['Ignoring', 'Danh sách exception được bỏ qua trong khi chờ.']] }, code: ['Wait<WebDriver> wait = new FluentWait<>(driver)', '    .withTimeout(Duration.ofSeconds(30))', '    .pollingEvery(Duration.ofSeconds(2))', '    .ignoring(NoSuchElementException.class);', '', 'WebElement result = wait.until(d -> d.findElement(By.id("result")));'], codeExplain: [['withTimeout(Duration.ofSeconds(30))', 'Tổng thời gian chờ tối đa.'], ['pollingEvery(Duration.ofSeconds(2))', 'Cứ 2 giây kiểm tra một lần.'], ['ignoring(NoSuchElementException.class)', 'Trong lúc chờ, NoSuchElementException được bỏ qua và thử lại.'], ['wait.until(d -> ...)', 'Điều kiện viết bằng lambda; d là driver.']], mistakes: [['Polling quá ngắn gây tải lớn.', 'Chọn chu kỳ hợp lý (ví dụ 500ms-2s).'], ['Ignore Exception quá rộng.', 'Chỉ ignore exception tạm thời đã hiểu rõ.'], ['Nghĩ FluentWait và WebDriverWait là hai thứ khác hẳn.', 'WebDriverWait mở rộng FluentWait.']], refs: [['Waits — Fluent waits', 'Mục FluentWait và tùy chọn', SEL + 'waits/'], ['FluentWait (Javadoc)', 'withTimeout, pollingEvery, ignoring', SELAPI + 'support/ui/FluentWait.html']] },

{ id: 11, day: 2, title: 'Dropdown, Checkbox và Radio Button', sub: 'Form controls: chọn, tích, và trạng thái', obj: ['Chọn option bằng Select (native select).', 'Dùng isSelected cho checkbox/radio.', 'Phân biệt dropdown native và dropdown tùy biến.'], theory: { what: 'Select là lớp hỗ trợ cho thẻ HTML <select> gốc. Checkbox và radio được kiểm tra trạng thái bằng isSelected.', why: 'Form có nhiều lựa chọn như tỉnh thành, điều khoản, giới tính.', when: 'Dùng Select khi là thẻ <select>. Dùng click cho checkbox/radio nếu cần đổi trạng thái.', how: 'Select.selectByVisibleText/selectByValue/selectByIndex chọn option. isSelected trả về trạng thái đã chọn.', whenNot: 'Select không dùng được cho dropdown tự tạo bằng div/ul; khi đó phải click từng bước.'}, beginner: { analogy: 'Dropdown native giống hộp chọn có sẵn trong văn phòng phẩm. Dropdown tùy biến là danh sách tự vẽ bằng hình — phải bấm mở rồi bấm chọn như một nút bình thường.', text: 'Radio button: chỉ được chọn một trong nhóm. Checkbox: tích nhiều được.', terms: [['Native', 'Thành phần chuẩn của HTML.'], ['Custom', 'Thành phần do lập trình viên tự làm.'], ['Option', 'Một lựa chọn trong dropdown.']] }, code: ['WebElement country = driver.findElement(By.id("country"));', 'Select select = new Select(country);', 'select.selectByVisibleText("Việt Nam");', 'WebElement terms = driver.findElement(By.id("terms"));', 'if (!terms.isSelected()) { terms.click(); }', 'boolean male = driver.findElement(By.id("male")).isSelected();'], codeExplain: [['new Select(country)', 'Bọc phần tử <select> để dùng các hàm chọn. Dùng cho thẻ select gốc.'], ['selectByVisibleText("Việt Nam")', 'Chọn option có text hiển thị đúng như vậy.'], ['if (!terms.isSelected()) click()', 'Chỉ bấm khi chưa tích, tránh bỏ tích ngoài ý muốn.'], ['isSelected()', 'Kiểm tra checkbox/radio đang được chọn chưa.']], mistakes: [['Dùng Select cho dropdown tùy biến.', 'Click mở dropdown rồi click option.'], ['Bấm checkbox đã tích sẵn, làm nó bỏ tích.', 'Kiểm tra isSelected trước.'], ['Nghĩ radio có thể tích nhiều cái.', 'Radio cùng name chỉ chọn một.']], refs: [['Select (Javadoc)', 'Lớp Select cho thẻ select', SELAPI + 'support/ui/Select.html'], ['HTML select (MDN)', 'Thẻ select', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Element/select'], ['Element interactions', 'Thao tác click và trạng thái', SEL + 'elements/interactions/']] },

{ id: 12, day: 2, title: 'Alerts (hộp thoại JavaScript)', sub: 'Accept, dismiss, prompt', obj: ['Xử lý alert, confirm, prompt.', 'Phân biệt accept và dismiss.', 'Hiểu NoAlertPresentException.'], theory: { what: 'Alert là hộp thoại JavaScript (alert, confirm, prompt) chặn trang cho đến khi người dùng đóng.', why: 'Khi có alert, lệnh tìm phần tử khác sẽ không hoạt động cho đến khi xử lý alert.', when: 'Khi ứng dụng gọi alert/confirm/prompt sau một hành động.', how: 'driver.switchTo().alert() lấy đối tượng alert; accept() bấm OK, dismiss() bấm Cancel, sendKeys() nhập vào prompt, getText() đọc nội dung.', whenNot: 'Không dùng cho popup trình duyệt riêng hay cửa sổ mới — đó là Window.'}, beginner: { analogy: 'Alert giống tờ giấy dán chặn ngay giữa cửa: bạn phải xé nó đi (OK hoặc Hủy) thì mới đi tiếp được.', text: 'Confirm có hai nút (OK/Cancel). Prompt có ô để nhập chữ.', terms: [['accept', 'Bấm OK.'], ['dismiss', 'Bấm Cancel/Hủy.'], ['switchTo', 'Chuyển ngữ cảnh điều khiển sang alert, frame hoặc cửa sổ.']] }, code: ['driver.findElement(By.id("delete")).click();', 'Alert confirm = driver.switchTo().alert();', 'System.out.println(confirm.getText());', 'confirm.dismiss();   // bấm Cancel', '', 'driver.findElement(By.id("name-prompt")).click();', 'Alert prompt = driver.switchTo().alert();', 'prompt.sendKeys("Minh");', 'prompt.accept();'], codeExplain: [['switchTo().alert()', 'Chuyển sự chú ý sang hộp thoại đang mở.'], ['getText()', 'Đọc nội dung alert.'], ['dismiss()', 'Bấm Cancel (confirm) hoặc hủy prompt.'], ['sendKeys("Minh")', 'Gõ vào ô của prompt.'], ['accept()', 'Bấm OK.']], mistakes: [['Gọi tìm phần tử khi alert đang mở.', 'Xử lý alert trước.'], ['Dùng accept khi cần dismiss.', 'Đọc kỹ đề bài: OK hay Hủy.'], ['Không xử lý alert rồi bị NoAlertPresentException.', 'Chờ alert xuất hiện bằng ExpectedConditions.alertIsPresent().']], refs: [['Alerts', 'Xử lý alert trong Selenium', SEL + 'interactions/alerts/'], ['Alert (Javadoc)', 'accept, dismiss, sendKeys', SELAPI + 'Alert.html'], ['NoAlertPresentException (Javadoc)', 'Khi không có alert', SELAPI + 'NoAlertPresentException.html']] },

{ id: 13, day: 2, title: 'iFrame và Nested Frames', sub: 'Trang con nằm trong trang', obj: ['Chuyển vào iframe bằng switchTo().frame().', 'Quay về trang chính bằng defaultContent() hoặc parentFrame().', 'Xử lý frame lồng nhau.'], theory: { what: 'iframe là một trang HTML con nằm trong trang chính. Mỗi frame có ngữ cảnh (context) riêng.', why: 'Widget thanh toán, quảng cáo, editor thường nằm trong iframe. Selenium không nhìn thấy phần tử trong iframe nếu chưa chuyển vào.', when: 'Khi phần tử không tìm thấy dù đã nhìn thấy trên màn hình — thử kiểm tra iframe.', how: 'switchTo().frame(...) đưa driver vào frame; defaultContent() về trang chính; parentFrame() lên một cấp.', whenNot: 'Không dùng khi phần tử đã nằm trong main document.'}, beginner: { analogy: 'Iframe giống một căn phòng bên trong nhà. Bạn muốn làm việc trong phòng đó thì phải bước vào; xong việc thì bước ra về sảnh chính (defaultContent).', text: 'Frame lồng nhau là phòng nằm trong phòng: phải đi từng cấp.', terms: [['iframe', 'Khung HTML chứa trang khác.'], ['Context', 'Ngữ cảnh nơi driver đang làm việc.'], ['defaultContent', 'Trang chính cao nhất.']] }, code: ['driver.switchTo().frame("payment-frame");', 'driver.findElement(By.id("card-number")).sendKeys("4111111111111111");', 'driver.switchTo().parentFrame();    // lên một cấp', 'driver.switchTo().defaultContent(); // về trang chính', 'driver.switchTo().frame(0);         // theo chỉ số (không khuyến nghị)'], codeExplain: [['frame("payment-frame")', 'Chuyển vào iframe theo id hoặc name.'], ['sendKeys(...)', 'Gõ vào phần tử trong frame.'], ['parentFrame()', 'Lên một tầng cha.'], ['defaultContent()', 'Về trang chính.'], ['frame(0)', 'Theo chỉ số: dễ sai khi thứ tự frame thay đổi.']], mistakes: [['Tìm phần tử bên trong frame khi vẫn đang ở main.', 'Chuyển vào frame trước.'], ['Quên quay về main document.', 'Gọi defaultContent() sau khi xong.'], ['Dùng chỉ số frame.', 'Dùng id hoặc name của frame.']], refs: [['Frames and iframes', 'Chuyển ngữ cảnh frame', SEL + 'interactions/frames/'], ['iframe (MDN)', 'Thẻ iframe', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Element/iframe'], ['TargetLocator (Javadoc)', 'switchTo().frame / defaultContent', SELAPI + 'WebDriver.TargetLocator.html']] },

{ id: 14, day: 2, title: 'Nhiều cửa sổ và tab', sub: 'Window handle và chuyển ngữ cảnh', obj: ['Lấy window handle hiện tại và danh sách handle.', 'Chuyển sang tab mới.', 'Đóng tab và quay lại tab cũ.'], theory: { what: 'Mỗi cửa sổ/tab có một window handle (chuỗi định danh). Driver làm việc với một cửa sổ tại một thời điểm.', why: 'Link mở tab mới là tình huống phổ biến; test phải chuyển sang tab đó.', when: 'Khi click mở tab/cửa sổ mới.', how: 'getWindowHandle() lấy handle hiện tại; getWindowHandles() lấy tập tất cả; switchTo().window(handle) chuyển.', whenNot: 'Không giả định thứ tự handle là cố định; luôn so sánh với tập trước đó.'}, beginner: { analogy: 'Mỗi tab giống một ngăn kéo có số hiệu riêng (handle). Bạn phải mở đúng ngăn kéo mới được lấy đồ. Không nên tin ngăn kéo nào đứng trước là ngăn kéo mới.', text: 'Cách an toàn: lưu handle cũ, click, chờ tập handle tăng lên, rồi lấy phần tử của handle mới.', terms: [['Window handle', 'Mã định danh của cửa sổ/tab.'], ['Tab', 'Một trang trong cùng trình duyệt.']] }, code: ['String mainHandle = driver.getWindowHandle();', 'driver.findElement(By.linkText("Chính sách")).click();', 'wait.until(d -> d.getWindowHandles().size() == 2);', 'for (String h : driver.getWindowHandles()) {', '    if (!h.equals(mainHandle)) { driver.switchTo().window(h); break; }', '}', 'driver.close();                       // đóng tab mới', 'driver.switchTo().window(mainHandle); // quay lại tab cũ'], codeExplain: [['getWindowHandle()', 'Lấy handle của tab hiện tại.'], ['wait.until(... size() == 2)', 'Chờ tab mới thật sự mở.'], ['for ... getWindowHandles()', 'Duyệt các handle, tìm handle khác với handle ban đầu.'], ['close()', 'Đóng tab đang chọn (tab mới).'], ['switchTo().window(mainHandle)', 'Quay về tab gốc.']], mistakes: [['Giả định handle thứ hai luôn là tab mới.', 'So sánh với handle ban đầu.'], ['Đóng tab rồi vẫn điều khiển tab đó.', 'Chuyển về handle còn mở trước khi thao tác tiếp.'], ['Không chờ tab mới mở xong.', 'Chờ theo số lượng handle.']], refs: [['Windows and tabs', 'Quản lý cửa sổ', SEL + 'interactions/windows/'], ['WebDriver.Window (Javadoc)', 'Các thao tác cửa sổ', SELAPI + 'WebDriver.Window.html'], ['TargetLocator (Javadoc)', 'switchTo().window', SELAPI + 'WebDriver.TargetLocator.html']] },

{ id: 15, day: 2, title: 'Actions Class', sub: 'Hover, drag-and-drop, tổ hợp phím', obj: ['Dùng Actions để hover, kéo thả, nhấn tổ hợp phím.', 'Hiểu build() và perform().'], theory: { what: 'Actions cho phép gộp nhiều thao tác nhập liệu (chuột, bàn phím) thành một chuỗi rồi thực hiện.', why: 'Menu hover, kéo thả, phím Ctrl+A không có một lệnh đơn giản.', when: 'Khi click/sendKeys thông thường không đủ.', how: 'Xây chuỗi bằng các phương thức (moveToElement, keyDown...), gọi build() để tạo hành động rồi perform() để chạy.', whenNot: 'Với thao tác click đơn giản, dùng click() trực tiếp.'}, beginner: { analogy: 'Actions giống một kịch bản diễn xuất: ghi lại các động tác (di chuột, giữ phím, thả), rồi diễn một lần.', text: 'Nhiều thao tác phải kết thúc bằng perform(); quên perform thì không có gì xảy ra.', terms: [['Hover', 'Đưa chuột lên phần tử.'], ['Drag and drop', 'Kéo phần tử và thả ở vị trí khác.']] }, code: ['Actions actions = new Actions(driver);', 'WebElement menu = driver.findElement(By.id("menu"));', 'actions.moveToElement(menu).perform();', '', 'WebElement src = driver.findElement(By.id("item"));', 'WebElement dst = driver.findElement(By.id("cart"));', 'actions.dragAndDrop(src, dst).perform();', '', 'actions.keyDown(Keys.CONTROL).sendKeys("a").keyUp(Keys.CONTROL).perform();'], codeExplain: [['new Actions(driver)', 'Tạo chuỗi hành động.'], ['moveToElement(menu).perform()', 'Di chuột vào menu để hiện submenu.'], ['dragAndDrop(src, dst)', 'Kéo từ nguồn đến đích.'], ['keyDown(Keys.CONTROL)...keyUp', 'Giữ Ctrl, gõ a, nhả Ctrl.']], mistakes: [['Quên perform().', 'Luôn kết thúc bằng perform().'], ['Dùng hover khi menu chỉ mở bằng click.', 'Xem ứng dụng mở menu thế nào.'], ['Dùng Actions trên phần tử đang bị che.', 'Chờ phần tử hiển thị và kiểm tra lớp che.']], refs: [['Actions API', 'Chuỗi hành động chuột và phím', SEL + 'actions_api/'], ['Actions (Javadoc)', 'moveToElement, dragAndDrop, perform', SELAPI + 'interactions/Actions.html'], ['Keyboard', 'Phím đặc biệt như Keys.CONTROL', SEL + 'keyboard/']] },

{ id: 16, day: 2, title: 'Các Exception thường gặp', sub: 'Đọc hiểu lỗi và sửa đúng', obj: ['Phân biệt NoSuchElement, StaleElementReference, ElementClickIntercepted, TimeoutException.', 'Biết hướng xử lý cho từng loại.'], theory: { what: 'Exception là tín hiệu lỗi do Selenium hoặc driver ném ra. Mỗi loại có nguyên nhân khác nhau.', why: 'Đọc đúng exception giúp sửa đúng nguyên nhân, không che lỗi bằng sleep.', when: 'Khi test đỏ, đọc loại exception trước.', how: 'NoSuchElement: không có phần tử khớp. StaleElementReference: tham chiếu cũ, DOM đã thay. ElementClickIntercepted: phần tử khác che. TimeoutException: điều kiện chờ không đạt kịp.', whenNot: 'Không bắt exception rồi bỏ qua im lặng.'}, beginner: { analogy: 'Giống bốn kiểu lỗi khi gọi món: không có món đó trong thực đơn (NoSuchElement); bạn cầm tờ phiếu cũ nhưng bếp đã làm lại phiếu mới (Stale); bàn bị đặt bát che (Intercepted); chờ quá lâu vẫn chưa có món (Timeout).', text: 'Đọc thông báo lỗi và dòng code gây lỗi trước khi sửa.', terms: [['Exception', 'Tín hiệu lỗi khi chạy.'], ['Stale', 'Đã cũ, không còn gắn với DOM hiện tại.'], ['Intercepted', 'Bị chặn bởi phần tử khác.']] }, code: ['try {', '    driver.findElement(By.id("ghost")).click();   // NoSuchElementException', '} catch (NoSuchElementException e) {', '    System.out.println("Không có phần tử ghost");', '}', 'WebElement row = driver.findElement(By.cssSelector("tr.item"));', 'driver.navigate().refresh();', 'row.getText();   // StaleElementReferenceException (row là tham chiếu cũ)', 'driver.findElement(By.id("buy")).click(); // có thể ElementClickInterceptedException'], codeExplain: [['try { ... } catch (...)', 'Bắt đúng loại exception để xử lý có chủ đích.'], ['refresh() rồi dùng row cũ', 'Làm DOM thay đổi nên tham chiếu cũ trở thành stale.'], ['click() bị chặn', 'Lớp phủ che nút; cần đóng lớp phủ hoặc chờ.']], mistakes: [['Bắt Exception rồi không làm gì.', 'Ghi log và để test fail đúng nơi.'], ['Thêm sleep để "giải quyết" stale.', 'Tìm lại phần tử sau khi DOM thay đổi.'], ['Nhầm Timeout với NoSuchElement.', 'Timeout là hết thời gian chờ; NoSuchElement là không tìm thấy phần tử sau khi áp dụng wait.']], refs: [['Troubleshooting errors', 'Các lỗi thường gặp trong Selenium', SEL + 'troubleshooting/errors/'], ['NoSuchElementException (Javadoc)', 'Mô tả ngoại lệ', SELAPI + 'NoSuchElementException.html'], ['StaleElementReferenceException (Javadoc)', 'Mô tả ngoại lệ', SELAPI + 'StaleElementReferenceException.html'], ['ElementClickInterceptedException (Javadoc)', 'Mô tả ngoại lệ', SELAPI + 'ElementClickInterceptedException.html']] },

{ id: 17, day: 3, title: 'TestNG, Annotation và vòng đời test', sub: 'Thứ tự chạy @Before/@After', obj: ['Hiểu các annotation chính.', 'Biết thứ tự chạy khi có nhiều test method.', 'Phân biệt BeforeTest và BeforeMethod, BeforeClass và BeforeMethod.'], theory: { what: 'TestNG là framework chạy test Java. Annotation như @Test, @BeforeMethod đánh dấu hàm và thời điểm chạy.', why: 'Cần chuẩn bị (mở browser) và dọn dẹp (đóng browser) cho test một cách nhất quán.', when: 'Mọi dự án Selenium Java thường dùng TestNG để quản lý test.', how: 'TestNG chạy suite → test → class → method theo thứ tự lifecycle. Mỗi @Test chạy trong vòng @BeforeMethod / @AfterMethod.', whenNot: 'Không đặt logic phụ thuộc giữa test độc lập vào cùng một method khi có thể tách riêng.'}, beginner: { analogy: 'Giống buổi biểu diễn: @BeforeSuite là chuẩn bị sân khấu cho cả lễ hội; @BeforeClass là chuẩn bị cho một vở; @BeforeMethod là thay trang phục trước mỗi cảnh.', text: 'Thứ tự đúng: BeforeSuite → BeforeTest → BeforeClass → BeforeMethod → Test → AfterMethod → AfterClass → AfterTest → AfterSuite.', terms: [['Annotation', 'Ghi chú bắt đầu bằng @ để báo cho framework biết cách chạy.'], ['Suite', 'Nhóm test lớn, định nghĩa trong testng.xml.'], ['Lifecycle', 'Vòng đời: các bước chạy trước và sau test.']] }, code: ['public class LoginTest {', '    WebDriver driver;', '', '    @BeforeClass', '    public void openBrowser() { driver = new ChromeDriver(); }', '', '    @BeforeMethod', '    public void goToLogin() { driver.get("https://example.com/login"); }', '', '    @Test', '    public void validLogin() { /* ... */ }', '', '    @AfterMethod', '    public void takeShotIfFailed() { /* ... */ }', '', '    @AfterClass', '    public void closeBrowser() { driver.quit(); }', '}'], codeExplain: [['@BeforeClass', 'Chạy một lần trước mọi test trong class: mở browser.'], ['@BeforeMethod', 'Chạy trước mỗi @Test: đưa trang về trạng thái bắt đầu.'], ['@Test', 'Đánh dấu một test case.'], ['@AfterMethod', 'Chạy sau mỗi test, dù pass hay fail.'], ['@AfterClass', 'Chạy một lần sau mọi test: đóng browser.']], mistakes: [['Đặt mở browser trong @BeforeMethod rồi mỗi test mở một browser nhưng không đóng.', 'Cân nhắc: BeforeClass cho browser, BeforeMethod cho trạng thái trang.'], ['Nhầm BeforeTest với BeforeMethod.', 'BeforeTest chạy một lần cho một thẻ <test> trong testng.xml; BeforeMethod chạy trước mỗi @Test.'], ['Phụ thuộc thứ tự giữa các @Test.', 'Mỗi test nên độc lập.']], refs: [['TestNG — Annotations', 'Danh sách annotation và thứ tự chạy', 'https://testng.org/#_annotations'], ['TestNG — Test methods', 'Cách test được chọn và chạy', 'https://testng.org/#_test_methods'], ['TestNG — testng.xml', 'Cấu hình suite', 'https://testng.org/#_testng_xml']] },

{ id: 18, day: 3, title: 'Hard Assert vs Soft Assert', sub: 'Dừng ngay hay gom lỗi rồi báo cáo', obj: ['Phân biệt hard assert (dừng ngay) và soft assert (gom lỗi).', 'Nhớ assertAll() là bắt buộc để soft assert báo lỗi.', 'Nhớ thứ tự tham số TestNG: actual trước expected.'], theory: { what: 'Hard assert (org.testng.Assert) ném AssertionError ngay khi sai và dừng test. SoftAssert ghi nhận lỗi và tiếp tục; assertAll() báo tổng hợp.', why: 'Hard assert tiết kiệm thời gian nhưng che các lỗi sau; soft assert kiểm tra nhiều điểm trong một lần chạy.', when: 'Hard assert cho điều kiện tiên quyết (đã đăng nhập chưa). Soft assert cho nhiều kiểm tra hiển thị.', how: 'SoftAssert lưu các kết quả; assertAll() ném lỗi tổng hợp nếu có ít nhất một lỗi.', whenNot: 'Soft assert không có assertAll() thì lỗi có thể bị bỏ qua — đây là lỗi nghiêm trọng.'}, beginner: { analogy: 'Hard assert giống giám khảo thổi còi dừng cuộc thi ngay khi bạn vấp. Soft assert giống giám khảo ghi lại mọi lỗi rồi cuối cùng mới công bố bảng điểm (assertAll).', text: 'TestNG: assertEquals(actual, expected). Thứ tự ngược với nhiều tài liệu khác, nên phải cẩn thận.', terms: [['Assertion', 'Khẳng định một điều phải đúng.'], ['Actual', 'Giá trị thực tế đọc được.'], ['Expected', 'Giá trị kỳ vọng.']] }, code: ['Assert.assertEquals(actualTitle, "Dashboard");   // hard: dừng ngay nếu sai', '', 'SoftAssert soft = new SoftAssert();', 'soft.assertEquals(userName, "Lan", "Tên người dùng");', 'soft.assertTrue(cartBadge.isDisplayed(), "Badge giỏ hàng");', 'soft.assertEquals(total, "250000", "Tổng tiền");', 'soft.assertAll();   // báo tất cả lỗi đã gom'], codeExplain: [['Assert.assertEquals(actual, expected)', 'Thứ tự TestNG: thực tế trước, kỳ vọng sau.'], ['SoftAssert soft = new SoftAssert()', 'Tạo bộ gom lỗi.'], ['soft.assertEquals(..., "message")', 'Ghi nhận; không dừng test.'], ['soft.assertAll()', 'Bắt buộc, báo tổng hợp lỗi.']], mistakes: [['Quên assertAll().', 'Luôn gọi ở cuối khối kiểm tra.'], ['Đổi thứ tự actual và expected.', 'TestNG là assertEquals(actual, expected).'], ['Dùng soft assert cho điều kiện tiên quyết.', 'Dùng hard assert khi bước sau không có ý nghĩa nếu bước trước sai.']], refs: [['TestNG — Asserts', 'Assert và SoftAssert', 'https://testng.org/#_asserts'], ['TestNG — Success, failure and assert', 'Cách TestNG đánh dấu pass/fail', 'https://testng.org/#_success_failure_and_assert'], ['SoftAssert (TestNG 7.9.0 Javadoc)', 'Lớp org.testng.asserts.SoftAssert: assertEquals/assertTrue và assertAll()', 'https://javadoc.io/static/org.testng/testng/7.9.0/org/testng/asserts/SoftAssert.html']] },

{ id: 19, day: 3, title: 'Page Object Model (POM)', sub: 'Tách locator và hành động ra khỏi test', obj: ['Hiểu POM là một mẫu thiết kế, không phải framework.', 'Biết vì sao sửa một locator ở một chỗ giúp nhiều test.', 'Phân biệt POM với PageFactory.'], theory: { what: 'POM là cách tổ chức code: mỗi trang có một class chứa locator và các hành động của trang. Test gọi các hành động đó.', why: 'Khi giao diện đổi, chỉ cần sửa một Page Object thay vì mọi test.', when: 'Dự án có nhiều test trên cùng một trang.', how: 'Test → Page Object → WebDriver → trình duyệt. Page Object có thể trả về Page Object khác để thể hiện chuyển trang.', whenNot: 'Test nhỏ, một file, chỉ vài bước — POM có thể thừa.'}, beginner: { analogy: 'Giống bộ điều khiển riêng cho từng căn phòng: nút bật đèn nằm trong phòng đó. Nếu công tắc đổi vị trí, chỉ sửa bộ điều khiển của căn phòng, không phải sửa mọi kịch bản.', text: 'POM là ý tưởng và quy ước đặt tên. Nó không phải thư viện hay framework kiểm thử.', terms: [['Page Object', 'Class đại diện cho một trang.'], ['Locator', 'Cách tìm phần tử nằm trong Page Object.'], ['PageFactory', 'Tiện ích của Selenium hỗ trợ khởi tạo Page Object với @FindBy.']] }, code: ['public class LoginPage {', '    private final WebDriver driver;', '    private final By userInput = By.id("username");', '    private final By loginBtn = By.id("login");', '', '    public LoginPage(WebDriver driver) { this.driver = driver; }', '', '    public DashboardPage login(String user, String pass) {', '        driver.findElement(userInput).sendKeys(user);', '        driver.findElement(By.id("password")).sendKeys(pass);', '        driver.findElement(loginBtn).click();', '        return new DashboardPage(driver);', '    }', '}'], codeExplain: [['By userInput = By.id("username")', 'Locator nằm một chỗ; sửa tại đây là đủ.'], ['public DashboardPage login(...)', 'Hành động của trang; trả về trang tiếp theo.'], ['return new DashboardPage(driver)', 'Mô tả chuyển trang.']], mistakes: [['Đặt assert trong Page Object.', 'Page Object nên thao tác; assert đặt trong test.'], ['Nghĩ POM là framework cài thêm.', 'POM là mẫu thiết kế; bạn tự viết class.'], ['Lộ locator ra ngoài test.', 'Giữ locator private trong Page Object.']], refs: [['Page Object Models', 'Hướng dẫn POM của Selenium', 'https://www.selenium.dev/documentation/test_practices/encouraged/page_object_models/'], ['PageFactory (Javadoc)', 'org.openqa.selenium.support.PageFactory', SELAPI + 'support/PageFactory.html'], ['By (Javadoc)', 'Các locator', SELAPI + 'By.html']] },

{ id: 20, day: 3, title: 'DataProvider và Data-driven Testing', sub: 'Một test chạy nhiều bộ dữ liệu', obj: ['Viết @DataProvider trả về Object[][].', 'Phân biệt dữ liệu tích cực và tiêu cực.', 'Biết khi nào dùng data-driven.'], theory: { what: 'DataProvider cung cấp nhiều bộ dữ liệu cho một @Test. TestNG chạy test một lần cho mỗi bộ.', why: 'Đăng nhập với nhiều tài khoản (đúng, sai mật khẩu, khóa) mà không copy test.', when: 'Khi logic test giống nhau, chỉ khác dữ liệu.', how: '@DataProvider(name="...") trả về Object[][]; @Test(dataProvider="...") nhận từng hàng qua tham số.', whenNot: 'Khi các kịch bản có logic khác nhau nhiều — tách thành test riêng.'}, beginner: { analogy: 'Giống một phiếu kiểm tra in sẵn nhiều đề: cùng cách làm bài nhưng đề khác nhau cho từng học sinh.', text: 'Dữ liệu tiêu cực (ví dụ mật khẩu sai) là để kiểm tra hệ thống báo lỗi đúng; không chỉ kiểm tra khi đúng.', terms: [['Data-driven', 'Điều khiển test bằng dữ liệu.'], ['Object[][]', 'Mảng hai chiều chứa dữ liệu.'], ['Positive / Negative', 'Dữ liệu đúng / dữ liệu sai.']] }, code: ['@DataProvider(name = "accounts")', 'public Object[][] accounts() {', '    return new Object[][] {', '        { "qa_user", "Pass@123", true },', '        { "qa_user", "wrong", false },', '        { "", "", false }', '    };', '}', '', '@Test(dataProvider = "accounts")', 'public void loginCheck(String user, String pass, boolean expectOk) {', '    // chạy login rồi assert kết quả theo expectOk', '}'], codeExplain: [['@DataProvider(name = "accounts")', 'Đặt tên cho nguồn dữ liệu.'], ['new Object[][] { {...}, {...} }', 'Mỗi dòng là một bộ dữ liệu.'], ['@Test(dataProvider = "accounts")', 'Test nhận dữ liệu theo từng dòng.'], ['boolean expectOk', 'Cột kỳ vọng giúp kiểm tra cả đúng và sai.']], mistakes: [['Chỉ có dữ liệu đúng.', 'Thêm dữ liệu sai để kiểm tra thông báo lỗi.'], ['Dữ liệu cứng trong test.', 'Tách vào DataProvider.'], ['Số tham số không khớp số cột.', 'Kiểm tra số cột và kiểu dữ liệu.']], refs: [['TestNG — Parameters with DataProviders', 'DataProvider và tham số', 'https://testng.org/#_parameters_with_dataproviders'], ['DataProvider (TestNG 7.9.0 Javadoc)', 'Annotation org.testng.annotations.DataProvider', 'https://javadoc.io/static/org.testng/testng/7.9.0/org/testng/annotations/DataProvider.html'], ['TestNG — Annotations', 'Annotation @DataProvider và @Test', 'https://testng.org/#_annotations'], ['Java documentation', 'Tài liệu Java chính thức (Oracle)', 'https://docs.oracle.com/en/java/']] }
];

/* ===== Cheat sheet ===== */
var CHEAT = [
['findElement vs findElements', 'Một phần tử / danh sách (có thể rỗng)', 'findElement(By.id("x")) / findElements(By.cssSelector(".item")).size()', 'findElement throws NoSuchElementException if none; findElements returns an empty list.'],
['close vs quit', 'close: đóng một cửa sổ; quit: đóng tất cả và kết thúc session', 'driver.close(); driver.quit();', 'close closes the current window; quit ends the whole WebDriver session.'],
['get vs navigate', 'Cùng mở URL; navigate có back/forward/refresh', 'driver.get(url); driver.navigate().to(url);', 'Both load a URL; navigate() also offers back, forward and refresh.'],
['XPath vs CSS Selector', 'XPath đi được lên cha, tìm theo text; CSS ngắn, nhanh đọc', '//button[text()="Save"] vs button.save', 'XPath can move up to parents and match text; CSS is shorter and usually easier to read.'],
['Absolute vs Relative XPath', 'Absolute đi từ /html; relative bắt đầu bằng //', '/html/body/div/input vs //input[@name="q"]', 'Relative XPath is preferred because it does not break when unrelated nodes change.'],
['Implicit vs Explicit vs Fluent Wait', 'Implicit: toàn session khi tìm; Explicit: theo điều kiện; Fluent: cấu hình polling', 'implicitlyWait / until(ExpectedConditions...) / new FluentWait', 'Implicit applies to element lookup; explicit waits for a specific condition; fluent adds polling and ignored exceptions.'],
['Presence vs Visibility vs Clickability', 'Có trong DOM / đang hiển thị / hiển thị + enabled + không bị che (điều kiện clickable không kiểm tra che)', 'presenceOfElementLocated / visibilityOfElementLocated / elementToBeClickable', 'Presence checks DOM; visibility checks display; clickable also checks enabled state.'],
['isDisplayed vs isEnabled vs isSelected', 'Hiển thị / được phép thao tác / đang được chọn', 'btn.isDisplayed(); btn.isEnabled(); chk.isSelected()', 'isDisplayed checks visibility, isEnabled checks whether the element can be used, isSelected checks checkboxes and radio buttons and options.'],
['getText vs getAttribute vs getDomAttribute', 'Chữ hiển thị / giá trị property-rồi-attribute / attribute trong DOM', 'el.getText(); el.getAttribute("href"); el.getDomAttribute("value")', 'getText reads visible text; getAttribute prefers property then attribute; getDomAttribute reads the DOM attribute.'],
['Alert vs iFrame vs Window', 'Alert: hộp thoại JS; iFrame: trang con; Window: tab/cửa sổ', 'switchTo().alert() / switchTo().frame() / switchTo().window()', 'Alert is a JS dialog, iframe is an embedded document, window is a browser tab or window.'],
['Hard Assert vs Soft Assert', 'Hard dừng ngay; Soft gom lỗi, cần assertAll()', 'Assert.assertEquals(a,e) / soft.assertAll()', 'Hard assert stops immediately; soft assert collects failures until assertAll() is called.'],
['BeforeTest vs BeforeMethod', 'BeforeTest: một lần cho thẻ <test>; BeforeMethod: trước mỗi @Test', '@BeforeTest / @BeforeMethod', 'BeforeTest runs once per <test> tag; BeforeMethod runs before every @Test method.'],
['BeforeClass vs BeforeMethod', 'BeforeClass: một lần cho class; BeforeMethod: mỗi test', '@BeforeClass / @BeforeMethod', 'BeforeClass runs once per class; BeforeMethod runs before each test method.'],
['POM vs PageFactory', 'POM là mẫu thiết kế; PageFactory là tiện ích khởi tạo @FindBy', 'new LoginPage(driver) / PageFactory.initElements(driver, this)', 'POM is a design pattern; PageFactory is a support helper that initializes @FindBy fields.'],
['NoSuchElement vs Timeout vs Stale', 'Không tìm thấy / hết giờ chờ điều kiện / tham chiếu cũ', 'findElement / wait.until / reuse after refresh', 'NoSuchElement: not found; Timeout: condition not met in time; Stale: reference no longer attached to DOM.'],
['Select vs click dropdown', 'Select chỉ cho thẻ select native; dropdown tùy biến phải click', 'new Select(el).selectByVisibleText("A")', 'Select works with native select elements only.']
];

